1	package server
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"log"
8		"mime"
9		"net/http"
10		"strconv"
11		"strings"
12	
13		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
14	)
15	
16	// maxBatchBytes caps an inbound POST body.
17	const maxBatchBytes = 10 << 20
18	
19	// defaultListLimit is used when GET omits limit.
20	const defaultListLimit = 100
21	
22	// maxListLimit is the largest page size GET accepts.
23	const maxListLimit = 1000
24	
25	type changeIn struct {
26		ID      string          `json:"id"`
27		Payload json.RawMessage `json:"payload"`
28	}
29	
30	type postRequest struct {
31		DeviceID string     `json:"deviceId"`
32		Changes  []changeIn `json:"changes"`
33	}
34	
35	type mergeChangeIn struct {
36		ID      string          `json:"id"`
37		Payload json.RawMessage `json:"payload"`
38	}
39	
40	type mergeRequest struct {
41		DeviceID   string          `json:"deviceId"`
42		BaseCursor json.RawMessage `json:"baseCursor"`
43		Change     *mergeChangeIn  `json:"change"`
44	}
45	
46	type snapshotPostRequest struct {
47		Cursor json.RawMessage `json:"cursor"`
48		State  json.RawMessage `json:"state"`
49	}
50	
51	type restoreRequest struct {
52		DeviceID       string          `json:"deviceId"`
53		ChangeID       string          `json:"changeId"`
54		SnapshotCursor json.RawMessage `json:"snapshotCursor"`
55	}
56	
57	type deviceRequest struct {
58		DeviceID string `json:"deviceId"`
59	}
60	
61	type permissionRequest struct {
62		DeviceID string `json:"deviceId"`
63		Action   string `json:"action"`
64	}
65	
66	type sessionRequest struct {
67		SessionID string `json:"sessionId"`
68	}
69	
70	// NewHandler builds the public HTTP surface backed by s.
71	func NewHandler(s *store.Store) http.Handler {
72		mux := http.NewServeMux()
73	
74		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
75			writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
76		})
77	
78		mux.HandleFunc("POST /v1/devices", func(w http.ResponseWriter, r *http.Request) {
79			handleRegisterDevice(s, w, r)
80		})
81		// Non-POST verbs on the exact collection path: the method-less pattern is
82		// less specific than POST above, so it only catches the rest and answers a
83		// JSON 404 instead of ServeMux's slash redirect.
84		mux.HandleFunc("/v1/devices", func(w http.ResponseWriter, _ *http.Request) {
85			writeError(w, http.StatusNotFound, "unknown device path")
86		})
87		mux.HandleFunc("/v1/sessions", func(w http.ResponseWriter, _ *http.Request) {
88			writeError(w, http.StatusNotFound, "unknown session path")
89		})
90		mux.HandleFunc("POST /v1/devices/{deviceId}/sessions", func(w http.ResponseWriter, r *http.Request) {
91			handleCreateSession(s, w, r)
92		})
93		mux.HandleFunc("DELETE /v1/devices/{deviceId}/sessions/{sessionId}", func(w http.ResponseWriter, r *http.Request) {
94			handleDeleteSession(s, w, r)
95		})
96		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments", func(w http.ResponseWriter, r *http.Request) {
97			handleCreateAttachment(s, w, r)
98		})
99		mux.HandleFunc("PUT /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
100			handlePutChunk(s, w, r)
101		})
102		mux.HandleFunc("POST /v1/devices/{deviceId}/attachments/{attachmentId}/complete", func(w http.ResponseWriter, r *http.Request) {
103			handleCompleteAttachment(s, w, r)
104		})
105		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}", func(w http.ResponseWriter, r *http.Request) {
106			handleGetAttachment(s, w, r)
107		})
108		mux.HandleFunc("GET /v1/devices/{deviceId}/attachments/{attachmentId}/chunks/{index}", func(w http.ResponseWriter, r *http.Request) {
109			handleGetChunk(s, w, r)
110		})
111		mux.HandleFunc("GET /v1/sessions/{sessionId}/documents/{documentId}/changes", func(w http.ResponseWriter, r *http.Request) {
112			handleSessionChanges(s, w, r)
113		})
114		// Any other path under the new namespaces is a JSON 404 rather than
115		// ServeMux's plain-text one: every failure of a new endpoint answers JSON.
116		// Exact method-patterns above take precedence over these subtree patterns.
117		mux.HandleFunc("/v1/devices/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
118			writeError(w, http.StatusNotFound, "unknown device/session path")
119		})
120		mux.HandleFunc("/v1/sessions/{rest...}", func(w http.ResponseWriter, _ *http.Request) {
121			writeError(w, http.StatusNotFound, "unknown session path")
122		})
123	
124		mux.HandleFunc("POST /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
125			handlePostChanges(s, w, r)
126		})
127		mux.HandleFunc("GET /v1/documents/{documentID}/changes", func(w http.ResponseWriter, r *http.Request) {
128			handleListChanges(s, w, r)
129		})
130		mux.HandleFunc("POST /v1/documents/{documentID}/merge", func(w http.ResponseWriter, r *http.Request) {
131			handleMergeChange(s, w, r)
132		})
133		mux.HandleFunc("POST /v1/documents/{documentID}/snapshots", func(w http.ResponseWriter, r *http.Request) {
134			handlePostSnapshot(s, w, r)
135		})
136		mux.HandleFunc("GET /v1/documents/{documentID}/snapshots/{cursor}", func(w http.ResponseWriter, r *http.Request) {
137			handleGetSnapshot(s, w, r)
138		})
139		mux.HandleFunc("POST /v1/documents/{documentID}/restore", func(w http.ResponseWriter, r *http.Request) {
140			handleRestore(s, w, r)
141		})
142		mux.HandleFunc("POST /v1/documents/{documentID}/permissions", func(w http.ResponseWriter, r *http.Request) {
143			handleSetPermission(s, w, r)
144		})
145	
146		// ServeMux treats any empty path segment (the doubled slash in
147		// /v1/documents//..., /v1/devices//sessions or
148		// /v1/sessions//documents/...) as an unclean path and answers with a 307
149		// HTML redirect (a 404 in a real client). The API contract is a 400 JSON
150		// error for an empty identifier, so intercept those paths before the mux
151		// sees them. A trailing slash empties the final id of the device/session
152		// routes and is rejected there for the same reason; the document routes
153		// keep their pre-existing ServeMux behavior.
154		return emptyIDGuard(mux)
155	}
156	
157	// emptyIDGuard rejects requests carrying an empty path identifier with a 400
158	// JSON error instead of letting ServeMux emit its HTML redirect or a
159	// plain-text 404.
160	//
161	// The document family keeps its original rule (an empty documentID, i.e. the
162	// prefix /v1/documents//); other odd paths there retain their old response so
163	// the pre-existing surface is unchanged. The new device/session families are
164	// stricter: any doubled slash (an empty deviceId, sessionId or documentId
165	// segment) or a trailing slash (an empty final id) is a 400 JSON error.
166	func emptyIDGuard(next http.Handler) http.Handler {
167		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
168			p := r.URL.Path
169	
170			documentSegmentEmpty := strings.HasPrefix(p, "/v1/documents//")
171			newFamilySegmentEmpty := false
172			if strings.HasPrefix(p, "/v1/devices/") || strings.HasPrefix(p, "/v1/sessions/") {
173				newFamilySegmentEmpty = strings.Contains(p, "//") || strings.HasSuffix(p, "/")
174			}
175	
176			if documentSegmentEmpty || newFamilySegmentEmpty {
177				writeError(w, http.StatusBadRequest, "path identifiers must be non-empty strings")
178				return
179			}
180			next.ServeHTTP(w, r)
181		})
182	}
183	
184	// Handler exposes the HTTP surface over a private in-memory store. Use
185	// NewHandler with a durable store for real deployments.
186	func Handler() http.Handler {
187		s, err := store.Open("")
188		if err != nil {
189			log.Fatalf("open in-memory store: %v", err)
190		}
191		return NewHandler(s)
192	}
193	
194	// decodeJSONBody enforces the strict POST contract shared by every JSON
195	// endpoint: Content-Type must be application/json, the body is capped at
196	// maxBatchBytes, it must contain exactly one JSON value, and no trailing data
197	// may follow it. Any violation writes a 400 JSON error and returns false; the
198	// caller returns immediately, so no handler reaches the store with malformed
199	// input and rejected requests write nothing.
200	func decodeJSONBody(w http.ResponseWriter, r *http.Request, dst any) bool {
201		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
202		if err != nil || mediaType != "application/json" {
203			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
204			return false
205		}
206	
207		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
208		dec := json.NewDecoder(r.Body)
209		if err := dec.Decode(dst); err != nil {
210			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
211			return false
212		}
213		// Reject trailing data after the JSON value.
214		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
215			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
216			return false
217		}
218		return true
219	}
220	
221	func handleRegisterDevice(s *store.Store, w http.ResponseWriter, r *http.Request) {
222		var req deviceRequest
223		if !decodeJSONBody(w, r, &req) {
224			return
225		}
226		if req.DeviceID == "" {
227			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
228			return
229		}
230	
231		created, err := s.RegisterDevice(req.DeviceID)
232		if err != nil {
233			writeError(w, http.StatusInternalServerError, "failed to register device")
234			return
235		}
236	
237		writeJSON(w, http.StatusOK, map[string]any{"deviceId": req.DeviceID, "created": created})
238	}
239	
240	func handleCreateSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
241		deviceID := r.PathValue("deviceId") // route pattern + guard guarantee non-empty
242	
243		var req sessionRequest
244		if !decodeJSONBody(w, r, &req) {
245			return
246		}
247		if req.SessionID == "" {
248			writeError(w, http.StatusBadRequest, "sessionId must be a non-empty string")
249			return
250		}
251	
252		created, err := s.CreateSession(deviceID, req.SessionID)
253		if err != nil {
254			var conflict *store.ErrSessionConflict
255			switch {
256			case errors.Is(err, store.ErrDeviceNotFound):
257				writeError(w, http.StatusNotFound, "device not found")
258			case errors.As(err, &conflict):
259				writeError(w, http.StatusConflict, "sessionId already belongs to another device: "+conflict.ID)
260			default:
261				writeError(w, http.StatusInternalServerError, "failed to create session")
262			}
263			return
264		}
265	
266		writeJSON(w, http.StatusOK, map[string]any{"sessionId": req.SessionID, "created": created})
267	}
268	
269	func handleDeleteSession(s *store.Store, w http.ResponseWriter, r *http.Request) {
270		deviceID := r.PathValue("deviceId")   // route pattern + guard guarantee non-empty
271		sessionID := r.PathValue("sessionId") // route pattern + guard guarantee non-empty
272	
273		if err := s.DeleteSession(deviceID, sessionID); err != nil {
274			if errors.Is(err, store.ErrSessionNotFound) {
275				writeError(w, http.StatusNotFound, "session not found")
276				return
277			}
278			writeError(w, http.StatusInternalServerError, "failed to delete session")
279			return
280		}
281	
282		writeJSON(w, http.StatusOK, map[string]bool{"deleted": true})
283	}
284	
285	func handlePostChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
286		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
287	
288		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
289		if err != nil || mediaType != "application/json" {
290			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
291			return
292		}
293	
294		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
295		var req postRequest
296		dec := json.NewDecoder(r.Body)
297		if err := dec.Decode(&req); err != nil {
298			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
299			return
300		}
301		// Reject trailing data after the JSON object.
302		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
303			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
304			return
305		}
306	
307		if req.DeviceID == "" {
308			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
309			return
310		}
311		if len(req.Changes) == 0 {
312			writeError(w, http.StatusBadRequest, "changes must be a non-empty array")
313			return
314		}
315	
316		changes := make([]store.Change, len(req.Changes))
317		seen := make(map[string]struct{}, len(req.Changes))
318		for i, c := range req.Changes {
319			if c.ID == "" {
320				writeError(w, http.StatusBadRequest, "each change must have a non-empty string id")
321				return
322			}
323			if len(c.Payload) == 0 {
324				writeError(w, http.StatusBadRequest, "each change must carry a JSON payload")
325				return
326			}
327			if _, dup := seen[c.ID]; dup {
328				writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+c.ID)
329				return
330			}
331			seen[c.ID] = struct{}{}
332			changes[i] = store.Change{ID: c.ID, DeviceID: req.DeviceID, Payload: c.Payload}
333		}
334	
335		results, err := s.PostChanges(documentID, changes)
336		if err != nil {
337			var conflict *store.ErrConflict
338			if errors.As(err, &conflict) {
339				writeError(w, http.StatusConflict, "change id already exists with different deviceId or payload: "+conflict.ID)
340				return
341			}
342			writeError(w, http.StatusInternalServerError, "failed to commit changes")
343			return
344		}
345	
346		writeJSON(w, http.StatusOK, map[string]any{"results": results})
347	}
348	
349	func handleMergeChange(s *store.Store, w http.ResponseWriter, r *http.Request) {
350		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
351	
352		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
353		if err != nil || mediaType != "application/json" {
354			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
355			return
356		}
357	
358		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
359		var req mergeRequest
360		dec := json.NewDecoder(r.Body)
361		if err := dec.Decode(&req); err != nil {
362			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
363			return
364		}
365		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
366			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
367			return
368		}
369	
370		if req.DeviceID == "" {
371			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
372			return
373		}
374		// baseCursor must be present and a non-negative integer (no fractions,
375		// strings, booleans or null).
376		if len(req.BaseCursor) == 0 {
377			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
378			return
379		}
380		baseCursor, ok := parseNonNegativeInt(req.BaseCursor)
381		if !ok {
382			writeError(w, http.StatusBadRequest, "baseCursor must be a non-negative integer")
383			return
384		}
385		if req.Change == nil {
386			writeError(w, http.StatusBadRequest, "change must be an object")
387			return
388		}
389		if req.Change.ID == "" {
390			writeError(w, http.StatusBadRequest, "change.id must be a non-empty string")
391			return
392		}
393		if len(req.Change.Payload) == 0 || !isJSONObject(req.Change.Payload) {
394			writeError(w, http.StatusBadRequest, "change.payload must be a JSON object")
395			return
396		}
397	
398		result, err := s.MergeChange(documentID, baseCursor, store.Change{
399			ID:       req.Change.ID,
400			DeviceID: req.DeviceID,
401			Payload:  req.Change.Payload,
402		})
403		if err != nil {
404			var conflict *store.ErrConflict
405			switch {
406			case errors.Is(err, store.ErrStaleCursor):
407				writeError(w, http.StatusBadRequest, "baseCursor is unknown or greater than the current cursor")
408				return
409			case errors.As(err, &conflict):
410				writeError(w, http.StatusConflict, "merge conflicts with existing changes: "+conflict.ID)
411				return
412			default:
413				writeError(w, http.StatusInternalServerError, "failed to merge change")
414				return
415			}
416		}
417	
418		writeJSON(w, http.StatusOK, result)
419	}
420	
421	func handlePostSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
422		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
423	
424		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
425		if err != nil || mediaType != "application/json" {
426			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
427			return
428		}
429	
430		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
431		var req snapshotPostRequest
432		dec := json.NewDecoder(r.Body)
433		if err := dec.Decode(&req); err != nil {
434			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
435			return
436		}
437		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
438			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
439			return
440		}
441	
442		cursor, ok := parseNonNegativeInt(req.Cursor)
443		if !ok {
444			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
445			return
446		}
447		if len(req.State) == 0 {
448			writeError(w, http.StatusBadRequest, "state is required")
449			return
450		}
451	
452		created, err := s.PutSnapshot(documentID, cursor, req.State)
453		if err != nil {
454			var conflict *store.ErrSnapshotConflict
455			switch {
456			case errors.Is(err, store.ErrSnapshotBase):
457				writeError(w, http.StatusBadRequest, "document is unknown or cursor is not an existing cursor")
458				return
459			case errors.As(err, &conflict):
460				writeError(w, http.StatusConflict, "snapshot already exists with a different state")
461				return
462			default:
463				writeError(w, http.StatusInternalServerError, "failed to store snapshot")
464				return
465			}
466		}
467	
468		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "created": created})
469	}
470	
471	func handleGetSnapshot(s *store.Store, w http.ResponseWriter, r *http.Request) {
472		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
473	
474		cursor, ok := parseCursorPath(r.PathValue("cursor"))
475		if !ok {
476			writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
477			return
478		}
479	
480		state, err := s.GetSnapshot(documentID, cursor)
481		if err != nil {
482			if errors.Is(err, store.ErrSnapshotNotFound) {
483				writeError(w, http.StatusNotFound, "snapshot not found")
484				return
485			}
486			writeError(w, http.StatusInternalServerError, "failed to load snapshot")
487			return
488		}
489	
490		writeJSON(w, http.StatusOK, map[string]any{"cursor": cursor, "state": state})
491	}
492	
493	func handleRestore(s *store.Store, w http.ResponseWriter, r *http.Request) {
494		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
495	
496		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
497		if err != nil || mediaType != "application/json" {
498			writeError(w, http.StatusBadRequest, "Content-Type must be application/json")
499			return
500		}
501	
502		r.Body = http.MaxBytesReader(w, r.Body, maxBatchBytes)
503		var req restoreRequest
504		dec := json.NewDecoder(r.Body)
505		if err := dec.Decode(&req); err != nil {
506			writeError(w, http.StatusBadRequest, "invalid JSON body: "+err.Error())
507			return
508		}
509		if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
510			writeError(w, http.StatusBadRequest, "invalid JSON body: unexpected trailing content")
511			return
512		}
513	
514		if req.DeviceID == "" {
515			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
516			return
517		}
518		if req.ChangeID == "" {
519			writeError(w, http.StatusBadRequest, "changeId must be a non-empty string")
520			return
521		}
522		// snapshotCursor must be present and a positive integer (no fractions,
523		// strings, booleans, null or zero).
524		if len(req.SnapshotCursor) == 0 {
525			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
526			return
527		}
528		snapshotCursor, ok := parsePositiveInt(req.SnapshotCursor)
529		if !ok {
530			writeError(w, http.StatusBadRequest, "snapshotCursor must be a positive integer")
531			return
532		}
533	
534		result, err := s.RestoreSnapshot(documentID, req.DeviceID, req.ChangeID, snapshotCursor)
535		if err != nil {
536			var conflict *store.ErrRestoreConflict
537			switch {
538			case errors.Is(err, store.ErrSnapshotNotFound):
539				writeError(w, http.StatusNotFound, "snapshot not found")
540				return
541			case errors.As(err, &conflict):
542				writeError(w, http.StatusConflict, "change id already exists with a different deviceId, snapshotCursor or source state: "+req.ChangeID)
543				return
544			default:
545				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
546				return
547			}
548		}
549	
550		writeJSON(w, http.StatusOK, result)
551	}
552	
553	// handleSetPermission grants or revokes a registered device's access to one
554	// document. Devices start authorized, so the first revoke is the first write;
555	// repeating the current state is idempotent (changed=false). A rejected
556	// request (bad content type, malformed JSON, trailing content, empty or
557	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
558	// unregistered device is a 404 JSON error.
559	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
560		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
561	
562		var req permissionRequest
563		if !decodeJSONBody(w, r, &req) {
564			return
565		}
566		if req.DeviceID == "" {
567			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
568			return
569		}
570		var authorized bool
571		switch req.Action {
572		case "grant":
573			authorized = true
574		case "revoke":
575			authorized = false
576		default:
577			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
578			return
579		}
580	
581		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
582		if err != nil {
583			if errors.Is(err, store.ErrDeviceNotFound) {
584				writeError(w, http.StatusNotFound, "device not found")
585				return
586			}
587			writeError(w, http.StatusInternalServerError, "failed to update permission")
588			return
589		}
590	
591		writeJSON(w, http.StatusOK, map[string]any{
592			"deviceId":   req.DeviceID,
593			"authorized": authorized,
594			"changed":    changed,
595		})
596	}
597	
598	// parseCursorPath reports whether raw is a decimal non-negative integer and
599	// returns its value. Signs, fractions and other adornments are rejected.
600	func parseCursorPath(raw string) (int64, bool) {
601		if raw == "" {
602			return 0, false
603		}
604		for _, c := range raw {
605			if c < '0' || c > '9' {
606				return 0, false
607			}
608		}
609		n, err := strconv.ParseInt(raw, 10, 64)
610		if err != nil {
611			return 0, false
612		}
613		return n, true
614	}
615	
616	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
617	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
618		var n int64
619		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
620			return 0, false
621		}
622		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
623		// require the literal to contain no fraction or exponent.
624		trimmed := strings.TrimSpace(string(raw))
625		if trimmed == "" || trimmed[0] == '-' {
626			return 0, false
627		}
628		for _, c := range trimmed {
629			if c < '0' || c > '9' {
630				return 0, false
631			}
632		}
633		return n, true
634	}
635	
636	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
637	// strings, booleans, null and negative numbers are rejected.
638	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
639		n, ok := parseNonNegativeInt(raw)
640		if !ok || n < 1 {
641			return 0, false
642		}
643		return n, true
644	}
645	
646	// isJSONObject reports whether raw decodes to a JSON object (not null, an
647	// array or a scalar).
648	func isJSONObject(raw json.RawMessage) bool {
649		var m map[string]json.RawMessage
650		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
651			return false
652		}
653		return true
654	}
655	
656	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
657		documentID := r.PathValue("documentID")
658	
659		after, limit, ok := parseChangesQuery(w, r)
660		if !ok {
661			return
662		}
663	
664		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
665		if err != nil {
666			writeError(w, http.StatusInternalServerError, "failed to list changes")
667			return
668		}
669	
670		writeChangesPage(w, changes, nextCursor)
671	}
672	
673	// handleSessionChanges is the session-scoped view of the existing change log:
674	// both path identifiers must be non-empty (the empty-segment guard rejects
675	// those before routing) and the session must currently exist, after which the
676	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
677	// the session's device has been revoked permission for the document, which is
678	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
679	// read; the change log itself is untouched.
680	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
681		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
682		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
683	
684		// Malformed query parameters are a request-shape error (400) checked
685		// before the resource lookup (404), matching the snapshot GET ordering.
686		after, limit, ok := parseChangesQuery(w, r)
687		if !ok {
688			return
689		}
690	
691		deviceID, err := s.SessionDevice(sessionID)
692		if err != nil {
693			if errors.Is(err, store.ErrSessionNotFound) {
694				writeError(w, http.StatusNotFound, "session not found")
695				return
696			}
697			writeError(w, http.StatusInternalServerError, "failed to look up session")
698			return
699		}
700	
701		authorized, err := s.DocumentAuthorized(documentID, deviceID)
702		if err != nil {
703			writeError(w, http.StatusInternalServerError, "failed to look up permission")
704			return
705		}
706		if !authorized {
707			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
708			return
709		}
710	
711		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
712		if err != nil {
713			writeError(w, http.StatusInternalServerError, "failed to list changes")
714			return
715		}
716	
717		writeChangesPage(w, changes, nextCursor)
718	}
719	
720	// parseChangesQuery parses the shared after/limit pagination parameters,
721	// writing the documented 400 on an illegal value. It is shared by the
722	// document-scoped and session-scoped change listings so their query semantics
723	// cannot drift apart.
724	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
725		q := r.URL.Query()
726	
727		after = 0
728		if raw := q.Get("after"); raw != "" {
729			v, err := strconv.ParseInt(raw, 10, 64)
730			if err != nil || v < 0 {
731				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
732				return 0, 0, false
733			}
734			after = v
735		}
736	
737		limit = defaultListLimit
738		if raw := q.Get("limit"); raw != "" {
739			v, err := strconv.ParseInt(raw, 10, 64)
740			if err != nil || v < 1 || v > maxListLimit {
741				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
742				return 0, 0, false
743			}
744			limit = v
745		}
746	
747		return after, limit, true
748	}
749	
750	// writeChangesPage renders a change listing page in the shared response shape.
751	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
752		writeJSON(w, http.StatusOK, map[string]any{
753			"changes":    changes,
754			"nextCursor": nextCursor,
755		})
756	}
757	
758	func writeJSON(w http.ResponseWriter, status int, v any) {
759		w.Header().Set("Content-Type", "application/json")
760		w.WriteHeader(status)
761		_ = json.NewEncoder(w).Encode(v)
762	}
763	
764	func writeError(w http.ResponseWriter, status int, message string) {
765		writeJSON(w, status, map[string]string{"error": message})
766	}
767

